(() => {
  const sections = [
    ["getting-started", "fa-rocket"], ["notes", "fa-note-sticky"],
    ["encryption", "fa-lock"], ["sharing", "fa-share-nodes"],
    ["security", "fa-user-shield"], ["astra-ai", "fa-wand-magic-sparkles"], ["plans", "fa-layer-group"], ["faq", "fa-circle-question"],
  ];
  const names = {
    en: ["Getting started", "Notes & storage", "Encryption", "Sharing & AstraDrop", "Account security", "Astra AI", "Plans & limits", "FAQ"],
    "zh-Hant": ["開始使用", "筆記與空間", "加密", "分享與 AstraDrop", "帳號安全", "Astra AI", "方案與限制", "常見問題"],
    ja: ["はじめに", "ノートと容量", "暗号化", "共有と AstraDrop", "アカウント保護", "Astra AI", "プランと制限", "よくある質問"],
  };
  const content = {
    "getting-started": {
      en: { title: "Start writing in minutes.", lead: "AstraNote keeps the first step small: make an account, make a note, find it anywhere.", body: `<h2 id="account">Create an account</h2><p>Choose a unique username, email address and strong password. Password recovery is intentionally unavailable, so use a password manager or another safe method to keep it. After signing in, your language and appearance preferences follow your account.</p><div class="docs-flow"><div><i class="fa-solid fa-user-plus"></i><strong>Create</strong><span>Choose your account details.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-note-sticky"></i><strong>Write</strong><span>Name a note and select protection.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-laptop-mobile"></i><strong>Return</strong><span>Open it from another device.</span></div></div><h2 id="first-note">Create your first note</h2><p>Give the note a clear title, then choose an encryption method before creating it. The title remains visible in every mode; the selected encryption method cannot be changed later. Write in the lined editor and press Save when you are ready. If you try to leave with unsaved changes, AstraNote asks first.</p><h2 id="find">Find it quickly</h2><p>Use My notes to search titles and content. Pin notes you reach often so they stay at the top. The dashboard shows your current plan, note count, storage use and recent notes. AstraNote is intentionally built for information you want to retrieve quickly, not for large files or images.</p>` },
      "zh-Hant": { title: "幾分鐘內，開始記下來。", lead: "AstraNote 讓開始這件事很簡單：建立帳號、建立筆記，然後在任何裝置找回它。", body: `<h2 id="account">建立帳號</h2><p>選擇不重複的使用者名稱、電子郵件與強密碼。AstraNote 刻意不提供密碼復原，請使用密碼管理器或其他安全方式保存密碼。登入後，語言與外觀偏好會跟隨帳號。</p><div class="docs-flow"><div><i class="fa-solid fa-user-plus"></i><strong>建立</strong><span>填寫帳號資料。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-note-sticky"></i><strong>書寫</strong><span>命名筆記並選擇保護方式。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-laptop-mobile"></i><strong>找回</strong><span>在另一台裝置開啟它。</span></div></div><h2 id="first-note">建立第一篇筆記</h2><p>先取一個清楚的標題，再選擇加密方式。所有模式都會保留標題可見；建立後不能變更加密方式。你可以在帶橫線的編輯器書寫，完成時再按儲存；若有未儲存內容就離開，AstraNote 會先詢問。</p><h2 id="find">快速找回</h2><p>在「我的筆記」搜尋標題與內容。常用內容可釘選到最上方；儀表板會顯示目前方案、筆記數量、用量與最近筆記。AstraNote 的設計目標是快速找回文字資訊，不是存放大型檔案或圖片。</p>` },
      ja: { title: "数分で、書き始める。", lead: "AstraNote は最初の一歩を小さくします。アカウントを作り、ノートを書き、どこでも見つけます。", body: `<h2 id="account">アカウントを作成</h2><p>重複しないユーザー名、メールアドレス、強いパスワードを選びます。AstraNote には意図的にパスワード復旧がないため、パスワードマネージャーなどで安全に保管してください。ログイン後は言語と外観がアカウントに同期されます。</p><div class="docs-flow"><div><i class="fa-solid fa-user-plus"></i><strong>作成</strong><span>アカウント情報を選びます。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-note-sticky"></i><strong>書く</strong><span>名前と保護方法を選びます。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-laptop-mobile"></i><strong>見つける</strong><span>別の端末から開きます。</span></div></div><h2 id="first-note">最初のノートを作成</h2><p>わかりやすいタイトルを付け、作成前に暗号化方式を選びます。タイトルはすべての方式で表示され、作成後に方式は変更できません。罫線付きエディターに書き、準備できたら保存します。未保存のまま離れる場合は確認されます。</p><h2 id="find">すぐに見つける</h2><p>「マイノート」でタイトルと内容を検索できます。よく使う内容はピン留めし、ダッシュボードでプラン、ノート数、容量、最近のノートを確認します。AstraNote は大きなファイルや画像ではなく、すぐ取り出す文章のためのものです。</p>` },
    },
    notes: {
      en: { title: "Keep a small library easy to use.", lead: "Storage is deliberate: every byte should help you find or recover something useful.", body: `<h2 id="organize">Search, pin and organize</h2><p>Search checks note titles and available content. Pinned notes always appear first. Plus, Pro and Ultra can archive or unarchive notes and use batch actions; these controls help keep a larger library calm without introducing folders or complicated workflows.</p><h2 id="storage">What uses storage?</h2><div class="docs-diagram"><div><i class="fa-solid fa-note-sticky"></i><strong>Notes</strong><span>Title, content and encryption data</span></div><div><i class="fa-solid fa-droplet"></i><strong>AstraDrop</strong><span>Each active snapshot</span></div><div><i class="fa-solid fa-clock-rotate-left"></i><strong>Recovery</strong><span>Previous version and trash</span></div><div class="docs-diagram-result"><strong>Your plan allowance</strong><span>All of the above are counted together</span></div></div><p>Account metadata and session records do not use your note quota. Encryption adds authenticated data around text, so encrypted notes use more storage. Very short notes can have noticeably larger relative overhead.</p><h2 id="recovery">Trash, versions and locked notes</h2><p>Ultra can keep one previous version and move unlocked notes to trash for a chosen period. They are recovery conveniences, not an independent backup. When a paid plan expires and use is above the active allowance, the largest active notes are locked first. A locked note remains readable and may be permanently deleted, but the server refuses editing, sharing, organization, recovery actions and new Drop creation until an adequate upgrade unlocks it.</p>` },
      "zh-Hant": { title: "讓小型筆記庫也很好找。", lead: "空間是刻意設計的：每一個位元組都該幫助你找回或復原有用內容。", body: `<h2 id="organize">搜尋、釘選與整理</h2><p>搜尋會檢查筆記標題與可用內容。釘選筆記永遠排在最前面。Plus、Pro、Ultra 可封存／解封並使用批次操作；它們讓較大的筆記庫保持安靜簡單，不引入複雜的資料夾流程。</p><h2 id="storage">哪些內容會占空間？</h2><div class="docs-diagram"><div><i class="fa-solid fa-note-sticky"></i><strong>筆記</strong><span>標題、內容與加密資料</span></div><div><i class="fa-solid fa-droplet"></i><strong>AstraDrop</strong><span>每一份有效快照</span></div><div><i class="fa-solid fa-clock-rotate-left"></i><strong>復原資料</strong><span>上一版本與垃圾桶</span></div><div class="docs-diagram-result"><strong>你的方案額度</strong><span>以上全部合併計算</span></div></div><p>帳號設定資料與工作階段不占筆記額度。加密會在文字外加入認證資料，因此會使用更多空間；非常短的筆記相對增加比例可能很明顯。</p><h2 id="recovery">垃圾桶、版本與鎖定筆記</h2><p>Ultra 可保留一個上一版本，並將未鎖定筆記移至垃圾桶一段指定時間。它們是復原便利功能，不是獨立備份。付費方案到期且用量超過目前額度時，最大的有效筆記會優先鎖定。鎖定筆記仍可閱讀與永久刪除；在升級到足夠額度前，後端會拒絕編輯、分享、整理、復原操作與建立新的 Drop。</p>` },
      ja: { title: "小さなノート庫を、使いやすく。", lead: "容量は意図的に使います。すべてのバイトは見つけることや復元に役立つべきです。", body: `<h2 id="organize">検索、ピン留め、整理</h2><p>検索はノート名と利用可能な内容を対象にします。ピン留めしたノートは常に先頭です。Plus、Pro、Ultra はアーカイブ、解除、一括操作を使えます。複雑なフォルダーを増やさず、大きなノート庫を落ち着いて保てます。</p><h2 id="storage">何が容量を使いますか？</h2><div class="docs-diagram"><div><i class="fa-solid fa-note-sticky"></i><strong>ノート</strong><span>タイトル、内容、暗号化データ</span></div><div><i class="fa-solid fa-droplet"></i><strong>AstraDrop</strong><span>有効な各スナップショット</span></div><div><i class="fa-solid fa-clock-rotate-left"></i><strong>復元データ</strong><span>直前の版とゴミ箱</span></div><div class="docs-diagram-result"><strong>プランの上限</strong><span>すべて合計して計算</span></div></div><p>アカウント設定とセッションはノート容量を使いません。暗号化には認証データが追加されるため、容量が増えます。短いノートでは相対的な増加が目立つことがあります。</p><h2 id="recovery">ゴミ箱、履歴、ロックされたノート</h2><p>Ultra は直前の版を一つ残し、ロックされていないノートを指定期間ゴミ箱へ移せます。これは復元の便利機能であり、独立したバックアップではありません。有料プラン終了後に使用量が上限を超えると、大きい有効ノートからロックされます。ロックされたノートは閲覧と完全削除ができますが、十分なアップグレードまで編集、共有、整理、復元、新しい Drop の作成はサーバー側で拒否されます。</p>` },
    },
    encryption: {
      en: { title: "Understand what each protection mode does.", lead: "Choose by sensitivity and recovery needs—not by the most impressive name.", body: `<h2 id="choose">Choose a mode</h2><div class="docs-encryption-grid"><div><h3>Not encrypted</h3><p>Smallest and fastest. For ordinary information.</p></div><div><h3>AES-128 / AES-256 GCM</h3><p>Authenticated server-managed encrypted storage.</p></div><div><h3>AstraSecret</h3><p>Client-side protection with your 4–6 digit PIN.</p></div><div><h3>AstraConfidential</h3><p>Stronger client-side flow using a 4–16 character ASCII PIN.</p></div><div class="docs-featured"><h3>AstraZero</h3><p>Pro and Ultra: the encryption key is generated entirely on the client. No server environment encryption key is used for this mode.</p></div></div><h2 id="flow">How client-side protection flows</h2><div class="docs-flow docs-flow--secure"><div><i class="fa-solid fa-key"></i><strong>Your PIN</strong><span>Kept by you, never stored as readable text.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-laptop-code"></i><strong>Your client</strong><span>Builds protection and encrypts content.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-server"></i><strong>Server</strong><span>Stores encrypted content, not readable text.</span></div></div><h2 id="boundaries">Security boundaries</h2><p>All modes leave note titles visible so you can identify notes. PIN-protected modes do not support normal note sharing because a recipient does not have the credentials needed to decrypt. Losing a PIN can make content permanently unreadable. Encryption cannot make a compromised device, malicious page code, stolen unlocked session or copied plaintext safe.</p><h2 id="zero">Why AstraZero is different</h2><p>AstraZero’s key is produced only on the client from its protected inputs. The server does not keep an equivalent environment key for it, and receives only encrypted output. This reduces what server-side file exposure alone can reveal, but does not remove your responsibility to protect your PIN and the device where you enter it.</p>` },
      "zh-Hant": { title: "了解每種保護實際做了什麼。", lead: "依照敏感程度與是否需要復原來選，而不是選名字最厲害的。", body: `<h2 id="choose">選擇方式</h2><div class="docs-encryption-grid"><div><h3>不加密</h3><p>最省空間、最快，適合一般資訊。</p></div><div><h3>AES-128 / AES-256 GCM</h3><p>由伺服器管理、具完整性驗證的加密儲存。</p></div><div><h3>AstraSecret</h3><p>使用你自己 4–6 位數字 PIN 的客戶端保護。</p></div><div><h3>AstraConfidential</h3><p>使用 4–16 位 ASCII PIN 的更強客戶端保護流程。</p></div><div class="docs-featured"><h3>AstraZero</h3><p>Pro 與 Ultra 可用：加密金鑰完全在客戶端產生，不使用此模式的伺服器環境加密金鑰。</p></div></div><h2 id="flow">客戶端保護流程</h2><div class="docs-flow docs-flow--secure"><div><i class="fa-solid fa-key"></i><strong>你的 PIN</strong><span>由你保存，不會以可讀文字儲存。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-laptop-code"></i><strong>你的客戶端</strong><span>建立保護並加密內容。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-server"></i><strong>伺服器</strong><span>儲存加密內容，不是可讀文字。</span></div></div><h2 id="boundaries">安全邊界</h2><p>所有模式都保留筆記標題可見，讓你辨識內容。使用 PIN 的模式不支援一般筆記分享，因為收件者沒有解密需要的憑證。遺失 PIN 可能使內容永久無法讀取。加密無法讓已被控制的裝置、惡意網頁、遭竊的已解鎖工作階段或已複製的明文變安全。</p><h2 id="zero">AstraZero 為何不同</h2><p>AstraZero 的金鑰僅在客戶端由受保護輸入產生。伺服器不保存相同的環境金鑰，只收到加密結果。這降低了只取得伺服器檔案時能直接看到的資訊，但你仍必須保護 PIN 與輸入它的裝置。</p>` },
      ja: { title: "各保護方式が実際にすることを知る。", lead: "最も強そうな名前ではなく、機密性と復元の必要性で選びます。", body: `<h2 id="choose">方式を選ぶ</h2><div class="docs-encryption-grid"><div><h3>暗号化なし</h3><p>最も軽く速い方式。通常の情報向けです。</p></div><div><h3>AES-128 / AES-256 GCM</h3><p>完全性確認を備えたサーバー管理型暗号化保存です。</p></div><div><h3>AstraSecret</h3><p>自分の 4〜6 桁 PIN を使うクライアント側保護です。</p></div><div><h3>AstraConfidential</h3><p>4〜16 文字 ASCII PIN を使う、より強いクライアント側保護フローです。</p></div><div class="docs-featured"><h3>AstraZero</h3><p>Pro と Ultra 向け。鍵はクライアントだけで生成され、この方式にサーバー環境の暗号鍵は使われません。</p></div></div><h2 id="flow">クライアント側保護の流れ</h2><div class="docs-flow docs-flow--secure"><div><i class="fa-solid fa-key"></i><strong>あなたの PIN</strong><span>自分で保管し、読める形では保存されません。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-laptop-code"></i><strong>あなたのクライアント</strong><span>保護を作り、内容を暗号化します。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-server"></i><strong>サーバー</strong><span>読める文章ではなく、暗号化内容を保存します。</span></div></div><h2 id="boundaries">保護の境界</h2><p>すべての方式でノートタイトルは識別のため表示されます。PIN 保護方式では、受信者に復号資格情報がないため通常共有を使えません。PIN を失うと内容が永久に読めなくなる場合があります。暗号化は、侵害済み端末、悪意あるページ、盗まれた解除済みセッション、複製済み平文を安全にはできません。</p><h2 id="zero">AstraZero が異なる理由</h2><p>AstraZero の鍵は保護された入力からクライアントだけで生成されます。サーバーは同等の環境鍵を持たず、暗号化結果だけを受け取ります。サーバーファイルだけの露出で直接見える情報を減らしますが、PIN と入力端末を守る責任は残ります。</p>` },
    },
  };
  const simple = (key, titles) => ({
    en: { title: titles[0], lead: titles[1], body: titles[2] },
    "zh-Hant": { title: titles[3], lead: titles[4], body: titles[5] },
    ja: { title: titles[6], lead: titles[7], body: titles[8] },
  });
  content.sharing = simple("sharing", [
    "Share deliberately, not permanently.", "A normal share link and AstraDrop solve different problems.", `<h2 id="links">Normal note sharing</h2><p>For an unencrypted, eligible note, create a difficult-to-guess read-only link. A reader can see the note, your public display name and masked email—not private account data. Disable sharing to revoke the link immediately.</p><h2 id="drop">AstraDrop</h2><p>AstraDrop creates a separate snapshot at <code>/drop/…</code>. Choose its required expiry and an optional view limit. It cannot be edited after creation, and its URL cannot be retrieved later; save it when it is shown. Every active Drop counts toward account storage.</p><h2 id="protection">Drop protection</h2><p>Basic Drops are stored as plaintext. AES, DropSecret and DropConfidential offer stronger protection when your plan permits. A Drop is not a live shared note: later edits to the source note do not change it.</p>`,
    "有意識地分享，而不是永久公開。", "一般分享連結與 AstraDrop 解決的是不同問題。", `<h2 id="links">一般筆記分享</h2><p>對符合資格且未加密的筆記，可建立難以猜測的唯讀連結。閱讀者可看到筆記、你的公開名稱與遮罩電子郵件，不能看到私人帳號資料。關閉分享即可立即撤銷連結。</p><h2 id="drop">AstraDrop</h2><p>AstraDrop 會建立 <code>/drop/…</code> 的獨立快照。必須設定到期時間，也可限制瀏覽次數。建立後不能編輯，網址之後無法取回，出現時請自行保存。每份有效 Drop 都會占用帳號空間。</p><h2 id="protection">Drop 保護</h2><p>基本 Drop 以純文字儲存。AES、DropSecret 與 DropConfidential 會依方案提供更強保護。Drop 不是即時分享筆記：日後編輯原筆記不會改變它。</p>`,
    "意図を持って共有し、永遠には公開しない。", "通常の共有リンクと AstraDrop は異なる用途に使います。", `<h2 id="links">通常ノートの共有</h2><p>対象となる未暗号化ノートでは、推測困難な読み取り専用リンクを作成できます。閲覧者に見えるのはノート、公開表示名、マスク済みメールだけで、非公開アカウント情報は見えません。共有をオフにすると直ちに無効化されます。</p><h2 id="drop">AstraDrop</h2><p>AstraDrop は <code>/drop/…</code> に独立したスナップショットを作成します。期限の設定が必須で、閲覧回数も制限できます。作成後は編集できず、URL は後から取得できません。表示時に保存してください。有効な Drop はアカウント容量を使います。</p><h2 id="protection">Drop の保護</h2><p>Basic Drop は平文保存です。AES、DropSecret、DropConfidential はプランに応じて強い保護を提供します。Drop はライブ共有ではないため、元ノートを後で編集しても変わりません。</p>`
  ]);
  content.security = simple("security", [
    "Keep access in your hands.", "Good encryption starts with a protected account and trusted device.", `<h2 id="sessions">Manage signed-in devices</h2><p>Settings lists up to five active sessions with a short browser label, IP address and available country. End any session you do not recognize. When a new session would exceed the limit, the least recently used older session is ended.</p><h2 id="secrets">Passwords and PINs</h2><p>Passwords are stored as hashes, not readable passwords. PINs are yours to retain; do not reuse them, do not put them in note titles, and enter them only on a device you trust. AstraNote cannot restore a forgotten PIN or password.</p><h2 id="limits">Protecting the service</h2><p>Rate limits, CSRF protection, signed sessions and human verification on irreversible actions help reduce abuse. These controls complement—not replace—your own device security and unique password.</p>`,
    "讓存取權一直在你手上。", "好的加密從受保護的帳號與可信任裝置開始。", `<h2 id="sessions">管理已登入裝置</h2><p>設定最多列出五個有效工作階段，顯示簡短瀏覽器名稱、IP 與可取得的國家。結束任何你不認得的工作階段。新工作階段超過上限時，最久未使用的舊工作階段會結束。</p><h2 id="secrets">密碼與 PIN</h2><p>密碼以雜湊保存，不是可讀密碼。PIN 必須由你自行保存；不要重複使用、不要放在筆記標題，且只在信任裝置輸入。AstraNote 無法復原忘記的 PIN 或密碼。</p><h2 id="limits">保護服務</h2><p>請求速率限制、CSRF 保護、簽署工作階段與不可逆操作的人類驗證可降低濫用。這些控制是補強，不取代你自己的裝置安全與不重複密碼。</p>`,
    "アクセスを自分の手に保つ。", "良い暗号化は、守られたアカウントと信頼できる端末から始まります。", `<h2 id="sessions">ログイン端末を管理</h2><p>設定には最大五つの有効なセッションが、短いブラウザ名、IP、利用可能な国情報とともに表示されます。覚えのないセッションは終了してください。上限を超える新規セッションでは、最も長く使われていない古いセッションが終了します。</p><h2 id="secrets">パスワードと PIN</h2><p>パスワードは読めるパスワードではなくハッシュとして保存されます。PIN は自分で保管し、再利用せず、ノートタイトルに書かず、信頼できる端末だけで入力してください。忘れた PIN やパスワードは復旧できません。</p><h2 id="limits">サービスの保護</h2><p>レート制限、CSRF 保護、署名付きセッション、不可逆操作の人間確認は乱用を減らします。これらは自分の端末保護と固有パスワードを補うもので、置き換えるものではありません。</p>`
  ]);
  content.plans = simple("plans", [
    "Know what your plan changes.", "Plans expand space and recovery tools; they do not change who owns your notes.", `<h2 id="allowance">Allowances</h2><p>Free includes 128 KB and 20 notes. Plus adds 256 KB and 50 notes. Pro adds 512 KB and unlimited notes. Ultra provides 1024 KB, unlimited notes, one previous version, configurable trash retention and priority manual support. The current <a href="/plans">Plans page</a> is the source of truth for products and prices.</p><h2 id="expiry">When paid time ends</h2><p>One month means 30 days. If your remaining entitlement changes, the highest active plan takes precedence. When an active allowance is exceeded after expiry, the largest notes are locked first. Upgrade to enough space to unlock them; do not rely on a grace period.</p><h2 id="deletion">Important limits</h2><p>Locked over-limit notes can be permanently removed after 30 days. Previous versions, trash and active AstraDrops use storage. Keep your own copy of important information and contact astranote@nxlabtw.com promptly about payment problems.</p>`,
    "知道方案真正改變了什麼。", "方案擴充空間與復原工具，不會改變筆記的所有權。", `<h2 id="allowance">額度</h2><p>Free 是 128 KB 與 20 篇筆記；Plus 為 256 KB 與 50 篇；Pro 為 512 KB 與無限筆記；Ultra 為 1024 KB、無限筆記、一個上一版本、可設定垃圾桶保留期與優先人工協助。最新產品與價格以<a href="/plans">方案頁</a>為準。</p><h2 id="expiry">付費時間結束時</h2><p>一個月固定為 30 天。剩餘權益改變時，最高的有效方案優先。到期後若用量超過有效額度，最大的筆記會先鎖定。升級至足夠空間才能解鎖，請不要依賴寬限期。</p><h2 id="deletion">重要限制</h2><p>超額鎖定筆記可能在 30 天後被永久刪除。上一版本、垃圾桶與有效 AstraDrop 都占空間。請自行保存重要資料副本，付款問題請盡快聯絡 astranote@nxlabtw.com。</p>`,
    "プランで何が変わるかを知る。", "プランは容量と復元機能を広げますが、ノートの所有権は変えません。", `<h2 id="allowance">上限</h2><p>Free は 128 KB と 20 ノート、Plus は 256 KB と 50 ノート、Pro は 512 KB と無制限ノート、Ultra は 1024 KB、無制限ノート、直前の版一つ、設定可能なゴミ箱期間、優先有人サポートを提供します。現在の商品と価格は<a href="/plans">プランページ</a>が基準です。</p><h2 id="expiry">有料期間の終了時</h2><p>一か月は 30 日です。残りの権利が変わる場合、最上位の有効プランが優先されます。期限後に使用量が上限を超えると、大きいノートからロックされます。解除には十分な容量へのアップグレードが必要で、猶予期間に依存しないでください。</p><h2 id="deletion">重要な制限</h2><p>上限超過でロックされたノートは 30 日後に永久削除される場合があります。直前の版、ゴミ箱、有効な AstraDrop は容量を使います。重要な情報は自分でもコピーを保管し、支払いの問題は astranote@nxlabtw.com へ早めに連絡してください。</p>`
  ]);
  content.faq = simple("faq", [
    "Answers before you need support.", "The questions that matter most when notes, access or protection are involved.", `<h2 id="password">Can AstraNote recover my password or PIN?</h2><p>No. Password recovery is not offered. PINs for protected notes are yours alone; losing one may make the note unreadable.</p><h2 id="titles">Are note titles encrypted?</h2><p>No. Titles remain visible in every mode so notes can be identified and organized. Choose titles that do not reveal sensitive information.</p><h2 id="share">Why can’t I share my protected note?</h2><p>PIN-protected note modes are intentionally tied to credentials a recipient does not have. Use an appropriate AstraDrop protection mode when you need an expiring separate snapshot.</p><h2 id="backup">Is trash or a previous version a backup?</h2><p>No. They are convenient recovery features and use your quota. Keep your own copies of important information.</p><h2 id="locked">Why is a note locked?</h2><p>Your current allowance is below your stored use after a plan change or expiry. Upgrade to sufficient capacity or permanently delete the locked note.</p>`,
    "在需要支援前先找到答案。", "當筆記、存取或保護出問題時，最重要的幾個問題。", `<h2 id="password">AstraNote 能復原我的密碼或 PIN 嗎？</h2><p>不能。服務不提供密碼復原。受保護筆記的 PIN 只由你持有；遺失可能使筆記無法讀取。</p><h2 id="titles">筆記標題有加密嗎？</h2><p>沒有。所有模式都保留標題可見，才能辨識與整理筆記。請不要在標題洩漏敏感資訊。</p><h2 id="share">為什麼不能分享受保護筆記？</h2><p>使用 PIN 的筆記模式刻意綁定在收件者沒有的憑證。需要限時獨立快照時，請使用合適的 AstraDrop 保護方式。</p><h2 id="backup">垃圾桶或上一版本是備份嗎？</h2><p>不是。它們是方便的復原功能且占用額度；重要資料仍應自行保存副本。</p><h2 id="locked">為什麼筆記被鎖定？</h2><p>方案變更或到期後，你目前額度低於已儲存用量。請升級到足夠容量，或永久刪除鎖定筆記。</p>`,
    "サポートが必要になる前の答え。", "ノート、アクセス、保護に関する最も重要な質問です。", `<h2 id="password">パスワードや PIN は復旧できますか？</h2><p>できません。パスワード復旧はありません。保護ノートの PIN は本人だけのもので、失うと読めなくなる可能性があります。</p><h2 id="titles">ノートタイトルは暗号化されますか？</h2><p>されません。すべての方式で識別と整理のためタイトルは表示されます。タイトルに機密情報を書かないでください。</p><h2 id="share">保護ノートを共有できないのはなぜですか？</h2><p>PIN 保護ノートは受信者が持たない資格情報に意図的に結び付けられています。期限付きの独立スナップショットには適切な AstraDrop 保護を使ってください。</p><h2 id="backup">ゴミ箱や直前の版はバックアップですか？</h2><p>いいえ。便利な復元機能であり、容量を使います。重要な情報は自分でもコピーを保管してください。</p><h2 id="locked">ノートがロックされた理由は？</h2><p>プラン変更または期限後、現在の上限が保存済み使用量より低くなっています。十分な容量へアップグレードするか、ロックされたノートを永久削除してください。</p>`
  ]);
  content.plans = {
    en: { title: "Choose the room and recovery you need.", lead: "Every plan keeps AstraNote fast. Paid plans add room, protection, organization, and a safer way back from mistakes.", body: `<section class="docs-plan-overview"><div class="docs-plan-grid"><article class="docs-plan-card docs-plan-plus"><header><i class="fa-solid fa-star" aria-hidden="true"></i><div><h2>Plus</h2><p>Keep everyday notes organized.</p></div></header><strong>0.000025 BTC <small>/ 30 days</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>256 KB · 50 notes</li><li><i class="fa-solid fa-thumbtack"></i>Pin, archive & batch actions</li><li><i class="fa-solid fa-user-shield"></i>AstraConfidential</li><li><i class="fa-solid fa-droplet"></i>DropSecret & protected Drops</li></ul><p>For a growing personal library that needs calm organization and stronger private text protection.</p></article><article class="docs-plan-card docs-plan-pro"><header><i class="fa-solid fa-gem" aria-hidden="true"></i><div><h2>Pro</h2><p>Privacy-focused, without limits on notes.</p></div></header><strong>0.000060 BTC <small>/ 30 days</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>512 KB · Infinity notes</li><li><i class="fa-solid fa-check"></i>Everything in Plus</li><li><i class="fa-solid fa-fingerprint"></i>AstraZero</li><li><i class="fa-solid fa-droplet"></i>DropConfidential</li></ul><p>For people who keep more sensitive text and want AstraZero’s client-only key generation.</p></article><article class="docs-plan-card docs-plan-ultra"><header><i class="fa-solid fa-crown" aria-hidden="true"></i><div><h2>Ultra</h2><p>More room, plus a way back.</p></div></header><strong>0.000125 BTC <small>/ 30 days</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>1024 KB · Infinity notes</li><li><i class="fa-solid fa-check"></i>Everything in Pro</li><li><i class="fa-solid fa-clock-rotate-left"></i>One previous version</li><li><i class="fa-solid fa-trash-can"></i>Trash & configurable retention</li></ul><p>For a larger note library where an accidental edit or deletion should not be final.</p></article></div><article class="docs-plan-free"><header><i class="fa-solid fa-feather" aria-hidden="true"></i><div><h2>Free</h2><p>Included for everyone, with no expiry.</p></div></header><ul><li>128 KB · 20 notes</li><li>AstraSecret</li><li>Basic AstraDrop</li><li>No ads or analytics tracking</li></ul></article></section><hr class="docs-rule"><section><h2 id="how-plans-work">How plan time and limits work</h2><div class="docs-plan-details"><div><i class="fa-solid fa-calendar-days"></i><h3>Time</h3><p>One month always means 30 days. When more than one paid plan remains active, Ultra is used first, then Pro, then Plus.</p></div><div><i class="fa-solid fa-lock"></i><h3>After expiry</h3><p>If stored use exceeds your active allowance, the largest notes are locked first. Their title and size remain visible; upgrade or permanently delete them.</p></div><div><i class="fa-solid fa-trash-can"></i><h3>Keep copies</h3><p>Locked over-limit notes may be permanently removed after 30 days. Trash and previous versions use storage and are not a backup.</p></div></div><p class="docs-callout"><i class="fa-solid fa-circle-info" aria-hidden="true"></i>See the <a href="/plans">Plans page</a> to purchase or renew. It always shows the current products and payment options.</p></section>` },
    "zh-Hant": { title: "選擇你需要的空間與復原方式。", lead: "每個方案都保留 AstraNote 的快速本質；付費方案增加空間、保護、整理與面對失誤時的回頭路。", body: `<section class="docs-plan-overview"><div class="docs-plan-grid"><article class="docs-plan-card docs-plan-plus"><header><i class="fa-solid fa-star" aria-hidden="true"></i><div><h2>Plus</h2><p>把日常筆記整理好。</p></div></header><strong>0.000025 BTC <small>/ 30 天</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>256 KB · 50 篇筆記</li><li><i class="fa-solid fa-thumbtack"></i>釘選、封存與批次操作</li><li><i class="fa-solid fa-user-shield"></i>AstraConfidential</li><li><i class="fa-solid fa-droplet"></i>DropSecret 與受保護 Drop</li></ul><p>適合開始成長的個人筆記庫，需要好整理，也希望私密文字有更強保護。</p></article><article class="docs-plan-card docs-plan-pro"><header><i class="fa-solid fa-gem" aria-hidden="true"></i><div><h2>Pro</h2><p>重視隱私，筆記數量無上限。</p></div></header><strong>0.000060 BTC <small>/ 30 天</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>512 KB · 無限筆記</li><li><i class="fa-solid fa-check"></i>包含 Plus 全部功能</li><li><i class="fa-solid fa-fingerprint"></i>AstraZero</li><li><i class="fa-solid fa-droplet"></i>DropConfidential</li></ul><p>適合保存更多敏感文字，希望使用 AstraZero 客戶端獨立產生金鑰的人。</p></article><article class="docs-plan-card docs-plan-ultra"><header><i class="fa-solid fa-crown" aria-hidden="true"></i><div><h2>Ultra</h2><p>更多空間，也保留回頭路。</p></div></header><strong>0.000125 BTC <small>/ 30 天</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>1024 KB · 無限筆記</li><li><i class="fa-solid fa-check"></i>包含 Pro 全部功能</li><li><i class="fa-solid fa-clock-rotate-left"></i>保留一個上一版本</li><li><i class="fa-solid fa-trash-can"></i>垃圾桶與可設定保留時間</li></ul><p>適合較大的筆記庫，不想讓一次誤改或誤刪就成為最後結果的人。</p></article></div><article class="docs-plan-free"><header><i class="fa-solid fa-feather" aria-hidden="true"></i><div><h2>Free</h2><p>所有人都包含，沒有到期日。</p></div></header><ul><li>128 KB · 20 篇筆記</li><li>AstraSecret</li><li>基本 AstraDrop</li><li>無廣告、無分析追蹤</li></ul></article></section><hr class="docs-rule"><section><h2 id="how-plans-work">方案時間與限制怎麼運作？</h2><div class="docs-plan-details"><div><i class="fa-solid fa-calendar-days"></i><h3>時間</h3><p>一個月固定為 30 天。同時擁有多個有效付費方案時，會先使用 Ultra，再來是 Pro、Plus。</p></div><div><i class="fa-solid fa-lock"></i><h3>到期後</h3><p>若已儲存用量超過目前額度，最大筆記會優先鎖定。仍可看見標題與大小；升級即可解鎖，也可永久刪除。</p></div><div><i class="fa-solid fa-trash-can"></i><h3>請自行留副本</h3><p>超額鎖定筆記可能在 30 天後永久刪除。垃圾桶與上一版本會占空間，並不是備份。</p></div></div><p class="docs-callout"><i class="fa-solid fa-circle-info" aria-hidden="true"></i>請到<a href="/plans">方案頁</a>購買或續費；該頁始終顯示目前商品與付款選項。</p></section>` },
    ja: { title: "必要な容量と復元を選ぶ。", lead: "どのプランでも AstraNote の速さはそのままです。有料プランでは容量、保護、整理、ミスから戻る方法を追加できます。", body: `<section class="docs-plan-overview"><div class="docs-plan-grid"><article class="docs-plan-card docs-plan-plus"><header><i class="fa-solid fa-star" aria-hidden="true"></i><div><h2>Plus</h2><p>日常ノートを整理する。</p></div></header><strong>0.000025 BTC <small>/ 30 日</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>256 KB · 50 ノート</li><li><i class="fa-solid fa-thumbtack"></i>ピン留め、アーカイブ、一括操作</li><li><i class="fa-solid fa-user-shield"></i>AstraConfidential</li><li><i class="fa-solid fa-droplet"></i>DropSecret と保護 Drop</li></ul><p>整理とより強い私的文章の保護が必要になった個人ノート庫向けです。</p></article><article class="docs-plan-card docs-plan-pro"><header><i class="fa-solid fa-gem" aria-hidden="true"></i><div><h2>Pro</h2><p>プライバシー重視、ノート数は無制限。</p></div></header><strong>0.000060 BTC <small>/ 30 日</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>512 KB · ノート無制限</li><li><i class="fa-solid fa-check"></i>Plus の全機能</li><li><i class="fa-solid fa-fingerprint"></i>AstraZero</li><li><i class="fa-solid fa-droplet"></i>DropConfidential</li></ul><p>より多くの重要な文章を保管し、AstraZero のクライアントのみの鍵生成を使いたい人向けです。</p></article><article class="docs-plan-card docs-plan-ultra"><header><i class="fa-solid fa-crown" aria-hidden="true"></i><div><h2>Ultra</h2><p>容量を増やし、戻る余地も残す。</p></div></header><strong>0.000125 BTC <small>/ 30 日</small></strong><ul><li><i class="fa-solid fa-hard-drive"></i>1024 KB · ノート無制限</li><li><i class="fa-solid fa-check"></i>Pro の全機能</li><li><i class="fa-solid fa-clock-rotate-left"></i>直前の版を一つ保持</li><li><i class="fa-solid fa-trash-can"></i>ゴミ箱と設定可能な保留期間</li></ul><p>大きめのノート庫で、誤編集や誤削除を最後の結果にしたくない人向けです。</p></article></div><article class="docs-plan-free"><header><i class="fa-solid fa-feather" aria-hidden="true"></i><div><h2>Free</h2><p>全員に含まれ、有効期限はありません。</p></div></header><ul><li>128 KB · 20 ノート</li><li>AstraSecret</li><li>Basic AstraDrop</li><li>広告なし・分析追跡なし</li></ul></article></section><hr class="docs-rule"><section><h2 id="how-plans-work">プラン期間と上限の仕組み</h2><div class="docs-plan-details"><div><i class="fa-solid fa-calendar-days"></i><h3>期間</h3><p>一か月は常に 30 日です。複数の有効な有料プランがある場合、Ultra、Pro、Plus の順で使われます。</p></div><div><i class="fa-solid fa-lock"></i><h3>期限後</h3><p>保存量が現在の上限を超えると、大きいノートからロックされます。タイトルとサイズは見え、アップグレードで解除するか永久削除できます。</p></div><div><i class="fa-solid fa-trash-can"></i><h3>自分用コピー</h3><p>上限超過でロックされたノートは 30 日後に永久削除される場合があります。ゴミ箱と直前の版は容量を使い、バックアップではありません。</p></div></div><p class="docs-callout"><i class="fa-solid fa-circle-info" aria-hidden="true"></i>購入や更新は<a href="/plans">プランページ</a>で行えます。現在の商品と支払い方法は常にそちらに表示されます。</p></section>` },
  };
  content["astra-ai"] = {
    en: { title: "Use Astra AI with intention.", lead: "Ask for a focused revision, inspect the preview, then decide whether it belongs in your note.", body: `<h2 id="what">What Astra AI does</h2><p>Astra AI helps revise the title and content of one note from an instruction you write. It returns a preview; nothing is changed until you choose <strong>Save changes</strong>.</p><div class="docs-flow"><div><i class="fa-solid fa-pen"></i><strong>Describe</strong><span>Say what should change.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-eye"></i><strong>Review</strong><span>Check the proposed title and text.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-floppy-disk"></i><strong>Choose</strong><span>Save it, or discard it.</span></div></div><h2 id="privacy">What is sent for a request?</h2><p>The title, content and your instruction are sent to OpenAI only when you choose Generate preview. For AstraSecret, AstraConfidential and AstraZero notes, the unlocked title and content are sent for that request; your PIN and encryption key are never sent or stored. Do not use Astra AI for content you do not want processed by that service.</p><h2 id="limits">Allowance and availability</h2><p>Astra AI has a separate allowance that refreshes every 30 days. The dashboard shows the remaining percentage. Free has access through the flexible service tier; paid plans have a larger allowance and can fall back to the standard tier when the flexible tier is temporarily unavailable. The feature is rate-limited to keep it fair for everyone.</p><h2 id="safe-use">Before you start</h2><p>Keep the Astra AI window open while it is working. Closing it, refreshing, or leaving AstraNote cancels the request and does not save anything. Always review the preview: AI output can be incomplete or wrong, and it is your decision whether to save it.</p>` },
    "zh-Hant": { title: "有意識地使用 Astra AI。", lead: "寫下清楚的修改方向、檢查預覽，再決定是否寫回筆記。", body: `<h2 id="what">Astra AI 能做什麼？</h2><p>Astra AI 可依照你的指令修改單篇筆記的標題與內容。它會先回傳預覽；你選擇<strong>儲存變更</strong>前，原筆記不會改動。</p><div class="docs-flow"><div><i class="fa-solid fa-pen"></i><strong>說明</strong><span>寫下希望如何修改。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-eye"></i><strong>確認</strong><span>檢查建議標題與內容。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-floppy-disk"></i><strong>選擇</strong><span>儲存，或捨棄結果。</span></div></div><h2 id="privacy">一次處理會傳送什麼？</h2><p>只有按下「產生預覽」時，筆記標題、內容與你的指令才會傳送到 OpenAI。AstraSecret、AstraConfidential、AstraZero 筆記會為本次處理傳送已解鎖的標題與內容；PIN 與加密金鑰絕不會傳送或儲存。不希望由該服務處理的內容，請不要使用 Astra AI。</p><h2 id="limits">額度與可用性</h2><p>Astra AI 有獨立額度，每 30 天重置；儀表板會顯示剩餘百分比。Free 透過彈性服務層使用；付費方案有更多額度，彈性服務暫時不可用時可改用標準服務層。功能有速率限制，確保每個人都能公平使用。</p><h2 id="safe-use">開始前</h2><p>處理中請保持 Astra AI 視窗開啟。關閉、重新整理或離開 AstraNote 會取消這次請求，且不會儲存任何內容。請務必確認預覽：AI 的結果可能不完整或錯誤，是否儲存永遠由你決定。</p>` },
    ja: { title: "意図を持って Astra AI を使う。", lead: "変更内容を明確に伝え、プレビューを確認してからノートへ保存するか決めます。", body: `<h2 id="what">Astra AI でできること</h2><p>Astra AI は、入力した指示に従って一つのノートのタイトルと内容を整えます。まずプレビューを返し、<strong>変更を保存</strong>するまで元のノートは変わりません。</p><div class="docs-flow"><div><i class="fa-solid fa-pen"></i><strong>指示する</strong><span>変えたいことを書きます。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-eye"></i><strong>確認する</strong><span>提案されたタイトルと文章を見ます。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-floppy-disk"></i><strong>選ぶ</strong><span>保存するか、結果を破棄します。</span></div></div><h2 id="privacy">リクエストで送信されるもの</h2><p>「プレビューを作成」を選んだ場合のみ、タイトル、内容、指示が OpenAI に送信されます。AstraSecret、AstraConfidential、AstraZero では解除済みのタイトルと内容がその処理のために送信されますが、PIN と暗号鍵は送信・保存されません。処理されたくない内容には Astra AI を使わないでください。</p><h2 id="limits">利用枠と可用性</h2><p>Astra AI には 30 日ごとに更新される独立した利用枠があり、ダッシュボードに残量の割合が表示されます。Free は Flex サービス階層で利用でき、有料プランにはより大きな枠があります。Flex が一時的に利用できない場合、有料プランは標準階層へ切り替わります。公平な利用のためレート制限があります。</p><h2 id="safe-use">始める前に</h2><p>処理中は Astra AI の画面を開いたままにしてください。閉じる、更新する、AstraNote から離れるとリクエストは中止され、何も保存されません。AI の出力は不完全または誤っている可能性があるため、必ずプレビューを確認してください。保存するかは常にあなたが決めます。</p>` },
  };
  content.faq = {
    en: { title: "Answers, clearly separated.", lead: "The practical details to know before you trust AstraNote with something useful.", body: `<dl class="docs-faq-list"><div><dt><b>Q</b> Can AstraNote recover my password or PIN?</dt><dd><b>A</b> No. Password recovery is unavailable, and your PIN is never recoverable by AstraNote. Keep both somewhere safe.</dd></div><div><dt><b>Q</b> Are note titles encrypted?</dt><dd><b>A</b> No. Titles stay visible in every mode so you can identify and organize notes. Do not put sensitive details in a title.</dd></div><div><dt><b>Q</b> Which encryption mode should I choose?</dt><dd><b>A</b> Use AstraSecret for everyday privacy, AstraConfidential for sensitive text with a strong ASCII PIN, and AstraZero when you want the key generated entirely on your client.</dd></div><div><dt><b>Q</b> Can a PIN-protected note be shared?</dt><dd><b>A</b> No. Normal sharing is unavailable because the recipient does not have what is needed to decrypt it. Use AstraDrop when an expiring snapshot is appropriate.</dd></div><div><dt><b>Q</b> Is AstraDrop a live note?</dt><dd><b>A</b> No. It is an uneditable snapshot with an expiry. Later edits to the original note do not change the Drop, and its URL cannot be retrieved later.</dd></div><div><dt><b>Q</b> Why is a note locked?</dt><dd><b>A</b> After a plan expires or changes, the largest notes are locked first if stored use exceeds your active allowance. Upgrade to unlock them or permanently delete them.</dd></div><div><dt><b>Q</b> Is the trash or previous version a backup?</dt><dd><b>A</b> No. They are recovery conveniences for Ultra and count toward storage. Keep an independent copy of important information.</dd></div><div><dt><b>Q</b> Why is storage measured in KB?</dt><dd><b>A</b> AstraNote is optimized for useful text, not files. Notes, encrypted data, active Drops and recovery copies count together; account settings and session records do not.</dd></div><div><dt><b>Q</b> Can I use AstraNote from another device?</dt><dd><b>A</b> Yes. Sign in to the same account. You can view and end other active sessions from Settings.</dd></div><div><dt><b>Q</b> Can I delete my account?</dt><dd><b>A</b> Yes. Account deletion is permanent. Review the confirmation carefully and save anything you need first.</dd></div></dl>` },
    "zh-Hant": { title: "問與答，清楚分開。", lead: "在把重要資訊交給 AstraNote 前，先知道這些實際細節。", body: `<dl class="docs-faq-list"><div><dt><b>問</b> AstraNote 能復原我的密碼或 PIN 嗎？</dt><dd><b>答</b> 不能。服務不提供密碼復原；PIN 也無法由 AstraNote 復原。請自行安全保存兩者。</dd></div><div><dt><b>問</b> 筆記標題有加密嗎？</dt><dd><b>答</b> 沒有。所有模式都保留標題可見，才能辨識與整理筆記。請不要把敏感資訊寫在標題。</dd></div><div><dt><b>問</b> 我該選哪種加密？</dt><dd><b>答</b> 日常私密可用 AstraSecret；敏感文字搭配強 ASCII PIN 可選 AstraConfidential；想讓金鑰完全由客戶端產生，則選 AstraZero。</dd></div><div><dt><b>問</b> 有 PIN 的筆記可以分享嗎？</dt><dd><b>答</b> 不行。一般分享不適用，因為收件者沒有解密所需內容。需要限時快照時，可使用 AstraDrop。</dd></div><div><dt><b>問</b> AstraDrop 是即時筆記嗎？</dt><dd><b>答</b> 不是。它是不可編輯、有期限的快照。之後編輯原筆記不會改變 Drop，網址也無法事後取回。</dd></div><div><dt><b>問</b> 為什麼筆記被鎖住？</dt><dd><b>答</b> 方案到期或變更後，若已儲存用量超過目前額度，最大筆記會優先鎖定。升級可解鎖，也可永久刪除它。</dd></div><div><dt><b>問</b> 垃圾桶或上一版本是備份嗎？</dt><dd><b>答</b> 不是。它們是 Ultra 的復原便利功能，也會計入用量。重要資料仍應自行保留另一份副本。</dd></div><div><dt><b>問</b> 為什麼空間用 KB 計算？</dt><dd><b>答</b> AstraNote 為有用文字而設計，不是檔案空間。筆記、加密資料、有效 Drop 與復原副本合併計算；帳號設定與工作階段不占用筆記額度。</dd></div><div><dt><b>問</b> 可以在別的裝置使用嗎？</dt><dd><b>答</b> 可以。登入相同帳號即可；也能在設定查看與登出其他有效工作階段。</dd></div><div><dt><b>問</b> 可以刪除帳號嗎？</dt><dd><b>答</b> 可以。帳號刪除是永久的，請在確認前先保存你需要的內容。</dd></div></dl>` },
    ja: { title: "質問と回答を、明確に。", lead: "役立つ情報を AstraNote に置く前に知っておきたい実用的な詳細です。", body: `<dl class="docs-faq-list"><div><dt><b>Q</b> パスワードや PIN は復旧できますか？</dt><dd><b>A</b> できません。パスワード復旧はなく、PIN も AstraNote では復旧できません。どちらも安全に保管してください。</dd></div><div><dt><b>Q</b> ノートタイトルは暗号化されますか？</dt><dd><b>A</b> されません。すべての方式で識別と整理のために表示されます。タイトルには機密情報を書かないでください。</dd></div><div><dt><b>Q</b> どの暗号化方式を選ぶべきですか？</dt><dd><b>A</b> 日常のプライバシーには AstraSecret、強い ASCII PIN を使う重要な文章には AstraConfidential、鍵をクライアントだけで生成したい場合は AstraZero が向きます。</dd></div><div><dt><b>Q</b> PIN 保護ノートは共有できますか？</dt><dd><b>A</b> できません。受信者は復号に必要なものを持たないためです。期限付きスナップショットには AstraDrop を使えます。</dd></div><div><dt><b>Q</b> AstraDrop はライブノートですか？</dt><dd><b>A</b> いいえ。編集できない期限付きスナップショットです。元ノートを編集しても変わらず、URL は後から取得できません。</dd></div><div><dt><b>Q</b> ノートがロックされた理由は？</dt><dd><b>A</b> プラン終了または変更後、保存量が現在の上限を超えると大きいノートからロックされます。アップグレードで解除するか、永久削除できます。</dd></div><div><dt><b>Q</b> ゴミ箱や直前の版はバックアップですか？</dt><dd><b>A</b> いいえ。Ultra の復元機能であり容量も使います。重要な情報は別のコピーも保管してください。</dd></div><div><dt><b>Q</b> 容量が KB 表示なのはなぜですか？</dt><dd><b>A</b> AstraNote はファイルではなく役立つ文章向けです。ノート、暗号化データ、有効な Drop、復元コピーは合算されます。アカウント設定とセッションはノート容量を使いません。</dd></div><div><dt><b>Q</b> 別の端末から使えますか？</dt><dd><b>A</b> はい。同じアカウントでログインしてください。設定で他の有効セッションを確認・終了できます。</dd></div><div><dt><b>Q</b> アカウントを削除できますか？</dt><dd><b>A</b> はい。アカウント削除は永久です。確認前に必要な内容を保存してください。</dd></div></dl>` },
  };
  content.home = {
    en: { title: "A notebook for what you need again.", lead: "AstraNote keeps short, useful text ready across your devices—without turning note-taking into a workspace.", body: `<h2 id="what">What AstraNote is for</h2><p>AstraNote is a focused online notebook for the details you want to retrieve quickly: a reference link, a short checklist, a code fragment, a reminder, study notes, or a private piece of text protected with the right mode. It is free to begin with, plain-text by design, and available wherever you can sign in.</p><h2 id="why">Why choose AstraNote?</h2><div class="docs-choice"><div><i class="fa-solid fa-bolt"></i><h3>Fast by default</h3><p>Open a note, write, save, and find it again without pages of workspace controls.</p></div><div><i class="fa-solid fa-mobile-screen-button"></i><h3>One small account</h3><p>Reach the same notes from a phone, tablet, or computer without moving files around.</p></div><div><i class="fa-solid fa-lock"></i><h3>Protection when it matters</h3><p>Choose from AES, AstraSecret, AstraConfidential, or AstraZero instead of making every note equally complicated.</p></div></div><h2 id="fit">When it fits—and when another tool fits better</h2><div class="docs-compare"><div><strong>Choose AstraNote for</strong><span>Quick text, frequently reused information, focused notes, and optional strong protection.</span></div><div><strong>Choose a document or drive for</strong><span>Large files, images, collaborative documents, spreadsheets, or a long-term file archive.</span></div></div><h2 id="space">Why begin with 128 KB?</h2><p>The free allowance is deliberately optimized for text, not files. It keeps the service lightweight, predictable, and fast while still holding a substantial collection of short notes. If your library grows, plans add more space and features. Your note titles, content, encrypted data, active Drops and recovery copies are counted clearly together.</p><h2 id="start">Start in three steps</h2><div class="docs-flow"><div><i class="fa-solid fa-user-plus"></i><strong>Create</strong><span>Make a separate AstraNote account.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-note-sticky"></i><strong>Write</strong><span>Name the note and choose protection.</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-magnifying-glass"></i><strong>Find</strong><span>Search or pin it when you need it.</span></div></div>` },
    "zh-Hant": { title: "把需要隨時找回的內容，放在手邊。", lead: "AstraNote 讓短小而有用的文字能跨裝置快速找回，不把記筆記變成一套複雜工作系統。", body: `<h2 id="what">AstraNote 適合做什麼？</h2><p>AstraNote 是專注的線上筆記本，適合保存想快速找回的內容：參考連結、簡短清單、程式片段、提醒、學習筆記，或依需求加密的私密文字。它免費就能開始、刻意採用純文字，也能在你登入的任何裝置使用。</p><h2 id="why">為什麼選擇 AstraNote？</h2><div class="docs-choice"><div><i class="fa-solid fa-bolt"></i><h3>預設就快速</h3><p>開啟、書寫、儲存、找回，不需要面對一整套工作空間控制項。</p></div><div><i class="fa-solid fa-mobile-screen-button"></i><h3>一個輕量帳號</h3><p>用手機、平板或電腦打開同一份筆記，不必來回搬移檔案。</p></div><div><i class="fa-solid fa-lock"></i><h3>需要時才加強保護</h3><p>可選 AES、AstraSecret、AstraConfidential 或 AstraZero，不必讓每篇筆記都變得複雜。</p></div></div><h2 id="fit">什麼時候適合？什麼時候該用其他工具？</h2><div class="docs-compare"><div><strong>適合 AstraNote</strong><span>快速文字、經常重複使用的資料、專注筆記，以及需要選擇性強保護的內容。</span></div><div><strong>適合文件或雲端硬碟</strong><span>大型檔案、圖片、多人協作文件、試算表，或長期檔案封存。</span></div></div><h2 id="space">為什麼免費方案從 128 KB 開始？</h2><p>免費額度刻意為文字而設計，不是為檔案而設計。它讓服務維持輕量、用量可預期且開啟快速，同時仍能容納大量短筆記。筆記庫成長後，可透過方案取得更多空間與功能。筆記標題、內容、加密資料、有效 Drop 與復原副本都會清楚合併計算。</p><h2 id="start">三步開始使用</h2><div class="docs-flow"><div><i class="fa-solid fa-user-plus"></i><strong>建立</strong><span>建立專用 AstraNote 帳號。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-note-sticky"></i><strong>書寫</strong><span>命名筆記並選擇保護方式。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-magnifying-glass"></i><strong>找回</strong><span>需要時搜尋或釘選它。</span></div></div>` },
    ja: { title: "また必要になることを、手元に。", lead: "AstraNote は短く役立つ文章を端末をまたいですぐ見つけられるようにし、ノートを複雑な作業空間にしません。", body: `<h2 id="what">AstraNote は何に向いていますか？</h2><p>AstraNote は、すぐ取り出したい内容のためのオンラインノートです。参照リンク、短いリスト、コード片、リマインダー、学習メモ、必要に応じて暗号化する私的な文章を保存できます。無料で始められ、プレーンテキストに特化し、ログインできる端末ならどこでも使えます。</p><h2 id="why">なぜ AstraNote？</h2><div class="docs-choice"><div><i class="fa-solid fa-bolt"></i><h3>最初から速い</h3><p>作業空間の操作に囲まれず、開く、書く、保存、見つけることに集中できます。</p></div><div><i class="fa-solid fa-mobile-screen-button"></i><h3>小さな一つのアカウント</h3><p>ファイルを移動せず、スマートフォン、タブレット、パソコンで同じノートを開けます。</p></div><div><i class="fa-solid fa-lock"></i><h3>必要なときの保護</h3><p>AES、AstraSecret、AstraConfidential、AstraZero を選べるため、すべてのノートを複雑にする必要はありません。</p></div></div><h2 id="fit">向いている場面と、別の道具が向く場面</h2><div class="docs-compare"><div><strong>AstraNote 向け</strong><span>すばやい文章、よく使う情報、集中したメモ、選択的に強く守りたい内容。</span></div><div><strong>文書・ドライブ向け</strong><span>大きなファイル、画像、共同編集文書、スプレッドシート、長期のファイル保管。</span></div></div><h2 id="space">なぜ無料は 128 KB から？</h2><p>無料枠はファイルではなく文章のために意図的に設計されています。サービスを軽く、予測可能で、速く保ちながら、短いノートを十分に保存できます。ライブラリが大きくなれば、プランで容量と機能を増やせます。タイトル、内容、暗号化データ、有効な Drop、復元コピーは明確に合算されます。</p><h2 id="start">三つの手順で始める</h2><div class="docs-flow"><div><i class="fa-solid fa-user-plus"></i><strong>作成</strong><span>専用 AstraNote アカウントを作ります。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-note-sticky"></i><strong>書く</strong><span>名前と保護方法を選びます。</span></div><i class="fa-solid fa-arrow-right"></i><div><i class="fa-solid fa-magnifying-glass"></i><strong>見つける</strong><span>必要なときに検索・ピン留めします。</span></div></div>` },
  };
  const encryptionGuide = {
    en: `<section class="docs-encryption-intro"><p>Every mode keeps the <strong>note title visible</strong> so you can recognize it. The content is what protection applies to.</p><div class="docs-encryption-map"><article><header><i class="fa-solid fa-key" aria-hidden="true"></i><div><h2>AstraSecret</h2><span>Everyday private text</span></div></header><div class="docs-key-path"><span><i class="fa-solid fa-hashtag" aria-hidden="true"></i>4–6 digit PIN</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>Client encrypts</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-server" aria-hidden="true"></i>Encrypted storage</span></div><ul><li>Your PIN is not stored as readable text.</li><li>Useful for everyday private information.</li><li>A short numeric PIN is convenient, not the strongest choice.</li></ul></article><article><header><i class="fa-solid fa-user-shield" aria-hidden="true"></i><div><h2>AstraConfidential</h2><span>Stronger personal protection</span></div></header><div class="docs-key-path"><span><i class="fa-solid fa-key" aria-hidden="true"></i>4–16 ASCII PIN</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>Client encrypts</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-shield-halved" aria-hidden="true"></i>Layered protection</span></div><ul><li>Use a unique 12–16 character PIN for the strongest result.</li><li>Your PIN stays with you and cannot be recovered.</li><li>Available with Plus and above.</li></ul></article><article class="docs-zero-card"><header><i class="fa-solid fa-fingerprint" aria-hidden="true"></i><div><h2>AstraZero</h2><span>The key begins entirely on your client</span></div><b>Pro · Ultra</b></header><div class="docs-zero-path"><span><i class="fa-solid fa-user-lock" aria-hidden="true"></i>Your PIN</span><i class="fa-solid fa-plus" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>Your client creates the key</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-server" aria-hidden="true"></i>Server receives ciphertext only</span></div><p><strong>No server environment key exists for AstraZero.</strong> Server access alone does not give someone a direct way to read the protected content.</p></article></div></section><hr class="docs-rule"><section><h2 id="compare">Choose at a glance</h2><div class="docs-protection-compare"><div class="docs-protection-head"><span>Mode</span><span>PIN</span><span>Where protection begins</span><span>Best fit</span></div><div><strong>AstraSecret</strong><span>4–6 digits</span><span>Your client</span><span>Everyday privacy</span></div><div><strong>AstraConfidential</strong><span>4–16 ASCII</span><span>Your client + account protection</span><span>Sensitive text</span></div><div class="is-zero"><strong>AstraZero</strong><span>4–16 ASCII</span><span>Your client only</span><span>Highest privacy focus</span></div></div><p class="docs-callout"><i class="fa-solid fa-circle-info" aria-hidden="true"></i>PIN-protected notes cannot use normal sharing. If you lose the PIN, AstraNote cannot restore the content. Encryption is not a backup, and it cannot protect a device already controlled by someone else.</p></section><hr class="docs-rule"><section><h2 id="zero">AstraZero after a server compromise</h2><div class="docs-zero-scenario"><div><i class="fa-solid fa-server" aria-hidden="true"></i><strong>Server data exposed</strong><span>Encrypted note data may be copied.</span></div><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><div><i class="fa-solid fa-lock" aria-hidden="true"></i><strong>Still encrypted</strong><span>The server has no equivalent AstraZero environment key.</span></div><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><div><i class="fa-solid fa-user-lock" aria-hidden="true"></i><strong>Your PIN remains needed</strong><span>Keep it private and use a trusted client.</span></div></div><div class="docs-calculator-card"><div><p class="eyebrow">REFERENCE ONLY</p><h3>PIN guess space</h3><p>These figures show the average number of guesses for a randomly generated PIN. They are a reference for comparing choices, not a prediction of a real attack.</p><label class="docs-calculator-label" for="zero-pin-length">PIN type</label><select id="zero-pin-length" class="docs-calculator"><option value="4d">4 digit PIN</option><option value="6d">6 digit PIN</option><option value="12a" selected>12 character ASCII PIN</option><option value="16a">16 character ASCII PIN</option></select></div><output class="docs-calculator-result" id="zero-guess-result" aria-live="polite"></output></div></section>`,
    "zh-Hant": `<section class="docs-encryption-intro"><p>所有方式都會保留<strong>筆記標題可見</strong>，讓你辨識筆記；受到保護的是內容。</p><div class="docs-encryption-map"><article><header><i class="fa-solid fa-key" aria-hidden="true"></i><div><h2>AstraSecret</h2><span>日常私密文字</span></div></header><div class="docs-key-path"><span><i class="fa-solid fa-hashtag" aria-hidden="true"></i>4–6 位數字 PIN</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>客戶端加密</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-server" aria-hidden="true"></i>儲存加密結果</span></div><ul><li>PIN 不會以可讀文字儲存。</li><li>適合日常需要保護的資訊。</li><li>短數字 PIN 很方便，但不是最強選擇。</li></ul></article><article><header><i class="fa-solid fa-user-shield" aria-hidden="true"></i><div><h2>AstraConfidential</h2><span>更強的個人保護</span></div></header><div class="docs-key-path"><span><i class="fa-solid fa-key" aria-hidden="true"></i>4–16 位 ASCII PIN</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>客戶端加密</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-shield-halved" aria-hidden="true"></i>分層保護</span></div><ul><li>建議用不重複、隨機的 12–16 位 PIN。</li><li>PIN 只由你保存，無法復原。</li><li>Plus 以上方案可用。</li></ul></article><article class="docs-zero-card"><header><i class="fa-solid fa-fingerprint" aria-hidden="true"></i><div><h2>AstraZero</h2><span>金鑰完全從你的客戶端開始產生</span></div><b>Pro · Ultra</b></header><div class="docs-zero-path"><span><i class="fa-solid fa-user-lock" aria-hidden="true"></i>你的 PIN</span><i class="fa-solid fa-plus" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>客戶端自行產生金鑰</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-server" aria-hidden="true"></i>伺服器只收到密文</span></div><p><strong>AstraZero 不依賴伺服器端的環境金鑰。</strong>只取得伺服器權限，無法直接讀取受保護內容。</p></article></div></section><hr class="docs-rule"><section><h2 id="compare">一眼選擇</h2><div class="docs-protection-compare"><div class="docs-protection-head"><span>方式</span><span>PIN</span><span>保護從哪裡開始</span><span>適合情況</span></div><div><strong>AstraSecret</strong><span>4–6 位數字</span><span>你的客戶端</span><span>日常私密</span></div><div><strong>AstraConfidential</strong><span>4–16 位 ASCII</span><span>客戶端＋帳號保護</span><span>敏感文字</span></div><div class="is-zero"><strong>AstraZero</strong><span>4–16 位 ASCII</span><span>只在你的客戶端</span><span>最重視隱私</span></div></div><p class="docs-callout"><i class="fa-solid fa-circle-info" aria-hidden="true"></i>使用 PIN 的筆記不能使用一般分享。遺失 PIN 時，AstraNote 無法替你還原內容。加密不是備份，也無法保護已被他人控制的裝置。</p></section><hr class="docs-rule"><section><h2 id="zero">伺服器權限外洩時的 AstraZero</h2><div class="docs-zero-scenario"><div><i class="fa-solid fa-server" aria-hidden="true"></i><strong>伺服器資料外洩</strong><span>加密後的筆記資料可能被複製。</span></div><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><div><i class="fa-solid fa-lock" aria-hidden="true"></i><strong>內容仍是密文</strong><span>伺服器沒有對應的 AstraZero 環境金鑰。</span></div><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><div><i class="fa-solid fa-user-lock" aria-hidden="true"></i><strong>仍需要你的 PIN</strong><span>請保密 PIN，並只在信任的客戶端輸入。</span></div></div><div class="docs-calculator-card"><div><p class="eyebrow">僅供參考</p><h3>PIN 猜測空間</h3><p>以下是隨機產生 PIN 平均需要的猜測次數，用來比較選項，不是對實際攻擊的預測。</p><label class="docs-calculator-label" for="zero-pin-length">PIN 類型</label><select id="zero-pin-length" class="docs-calculator"><option value="4d">4 位數字 PIN</option><option value="6d">6 位數字 PIN</option><option value="12a" selected>12 位 ASCII PIN</option><option value="16a">16 位 ASCII PIN</option></select></div><output class="docs-calculator-result" id="zero-guess-result" aria-live="polite"></output></div></section>`,
    ja: `<section class="docs-encryption-intro"><p>すべての方式で<strong>ノートタイトルは表示</strong>され、内容に保護が適用されます。</p><div class="docs-encryption-map"><article><header><i class="fa-solid fa-key" aria-hidden="true"></i><div><h2>AstraSecret</h2><span>日常の私的な文章</span></div></header><div class="docs-key-path"><span><i class="fa-solid fa-hashtag" aria-hidden="true"></i>4〜6 桁 PIN</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>クライアントで暗号化</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-server" aria-hidden="true"></i>暗号化して保存</span></div><ul><li>PIN は読める形で保存されません。</li><li>日常の私的な情報に向きます。</li><li>短い数字 PIN は便利ですが、最も強い選択ではありません。</li></ul></article><article><header><i class="fa-solid fa-user-shield" aria-hidden="true"></i><div><h2>AstraConfidential</h2><span>より強い個人保護</span></div></header><div class="docs-key-path"><span><i class="fa-solid fa-key" aria-hidden="true"></i>4〜16 文字 ASCII PIN</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>クライアントで暗号化</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-shield-halved" aria-hidden="true"></i>段階的な保護</span></div><ul><li>固有でランダムな 12〜16 文字 PIN を推奨します。</li><li>PIN は本人だけが保管し、復旧できません。</li><li>Plus 以上で利用できます。</li></ul></article><article class="docs-zero-card"><header><i class="fa-solid fa-fingerprint" aria-hidden="true"></i><div><h2>AstraZero</h2><span>鍵はあなたのクライアントだけで生成</span></div><b>Pro · Ultra</b></header><div class="docs-zero-path"><span><i class="fa-solid fa-user-lock" aria-hidden="true"></i>あなたの PIN</span><i class="fa-solid fa-plus" aria-hidden="true"></i><span><i class="fa-solid fa-laptop-code" aria-hidden="true"></i>クライアントが鍵を生成</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><span><i class="fa-solid fa-server" aria-hidden="true"></i>サーバーには暗号文だけ</span></div><p><strong>AstraZero はサーバー環境の暗号鍵に依存しません。</strong>サーバーアクセスだけで保護された内容を直接読むことはできません。</p></article></div></section><hr class="docs-rule"><section><h2 id="compare">ひと目で選ぶ</h2><div class="docs-protection-compare"><div class="docs-protection-head"><span>方式</span><span>PIN</span><span>保護の開始地点</span><span>向く用途</span></div><div><strong>AstraSecret</strong><span>4〜6 桁</span><span>あなたのクライアント</span><span>日常のプライバシー</span></div><div><strong>AstraConfidential</strong><span>4〜16 ASCII</span><span>クライアント＋アカウント保護</span><span>重要な文章</span></div><div class="is-zero"><strong>AstraZero</strong><span>4〜16 ASCII</span><span>あなたのクライアントのみ</span><span>プライバシーを最優先</span></div></div><p class="docs-callout"><i class="fa-solid fa-circle-info" aria-hidden="true"></i>PIN 保護ノートは通常共有を使えません。PIN を失うと AstraNote は内容を復元できません。暗号化はバックアップではなく、他者に制御された端末は守れません。</p></section><hr class="docs-rule"><section><h2 id="zero">サーバーアクセス露出時の AstraZero</h2><div class="docs-zero-scenario"><div><i class="fa-solid fa-server" aria-hidden="true"></i><strong>サーバーデータが露出</strong><span>暗号化ノートのデータはコピーされる可能性があります。</span></div><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><div><i class="fa-solid fa-lock" aria-hidden="true"></i><strong>内容は暗号文のまま</strong><span>サーバーに同等の AstraZero 環境鍵はありません。</span></div><i class="fa-solid fa-arrow-right" aria-hidden="true"></i><div><i class="fa-solid fa-user-lock" aria-hidden="true"></i><strong>あなたの PIN が必要</strong><span>PIN は秘密にし、信頼できるクライアントでだけ入力してください。</span></div></div><div class="docs-calculator-card"><div><p class="eyebrow">参考用</p><h3>PIN の推測空間</h3><p>ランダムに生成された PIN に必要となる平均推測回数です。選択肢を比べる参考であり、実際の攻撃の予測ではありません。</p><label class="docs-calculator-label" for="zero-pin-length">PIN の種類</label><select id="zero-pin-length" class="docs-calculator"><option value="4d">4 桁数字 PIN</option><option value="6d">6 桁数字 PIN</option><option value="12a" selected>12 文字 ASCII PIN</option><option value="16a">16 文字 ASCII PIN</option></select></div><output class="docs-calculator-result" id="zero-guess-result" aria-live="polite"></output></div></section>`,
  };
  const encryptionExtra = {
    en: `<hr class="docs-rule"><h2 id="secret">AstraSecret: everyday privacy</h2><p>AstraSecret protects content on the client with a 4–6 digit PIN you keep. It is useful when you want a simple extra barrier for everyday private text. A short numeric PIN has limited guessing resistance, so do not treat it as the strongest choice for high-value secrets.</p><hr class="docs-rule"><h2 id="confidential">AstraConfidential: stronger user-held protection</h2><p>AstraConfidential uses a case-sensitive 4–16 character printable-ASCII PIN. A unique, randomly generated 12–16 character PIN is strongly preferred. The client encrypts content before upload and combines account-bound protection with server-side protection; the PIN is never stored or recoverable.</p><hr class="docs-rule"><h2 id="zero">AstraZero: key generation stays on your client</h2><p>AstraZero is the strongest privacy-oriented mode. Its encryption key is generated entirely on your client; there is no equivalent server environment key to obtain. A server compromise alone leaves an attacker with encrypted data, not direct plaintext.</p><div class="docs-zero-model"><i class="fa-solid fa-shield-halved" aria-hidden="true"></i><div><strong>If server access is exposed</strong><span>The attacker still needs your PIN, control of a trusted client while it is unlocked, or a successful attack against another boundary. Server access by itself is not enough to directly read an AstraZero note.</span></div></div><h3>PIN guess-space, not a promised crack time</h3><p>We cannot honestly state one fixed amount of computing power or a fixed crack time: it depends on whether the PIN is random, its length, the attacker’s hardware, and the actual attack path. For a uniformly random PIN using 94 permitted printable ASCII characters, the average offline guess count is <code>94ⁿ ÷ 2</code>.</p><label class="docs-calculator-label" for="zero-pin-length">Illustrative random PIN length</label><select id="zero-pin-length" class="docs-calculator"><option value="4">4 characters</option><option value="8">8 characters</option><option value="12" selected>12 characters</option><option value="16">16 characters</option></select><p class="docs-calculator-result" id="zero-guess-result" aria-live="polite"></p><p class="docs-callout"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i>A human-chosen or reused PIN can have far less entropy than this illustration. The calculator never asks for or receives your actual PIN.</p>`,
    "zh-Hant": `<hr class="docs-rule"><h2 id="secret">AstraSecret：日常私密保護</h2><p>AstraSecret 以你自行保存的 4–6 位數字 PIN，在客戶端保護內容。它適合希望為日常私密文字多加一道保護的人；但短數字 PIN 的抗猜測能力有限，不應把它當成高價值機密的最強選擇。</p><hr class="docs-rule"><h2 id="confidential">AstraConfidential：更強的使用者持有保護</h2><p>AstraConfidential 使用區分大小寫、4–16 字元的可列印 ASCII PIN。強烈建議使用不重複、隨機產生的 12–16 字元 PIN。內容會先在客戶端加密再上傳，並結合帳號綁定與伺服器端保護；PIN 不會被儲存，也無法復原。</p><hr class="docs-rule"><h2 id="zero">AstraZero：金鑰只在你的客戶端產生</h2><p>AstraZero 是最重視隱私的模式。它的加密金鑰完全在你的客戶端產生，伺服器不存在可取得的相同環境金鑰。僅取得伺服器權限或檔案，攻擊者拿到的是加密資料，而不是可直接讀取的明文。</p><div class="docs-zero-model"><i class="fa-solid fa-shield-halved" aria-hidden="true"></i><div><strong>如果伺服器權限外洩</strong><span>攻擊者仍須取得你的 PIN、控制可信任裝置在解鎖時的狀態，或成功突破另一個安全邊界。只有伺服器權限，不能直接讀取 AstraZero 筆記。</span></div></div><h3>PIN 猜測空間，不是假裝精準的破解時間</h3><p>我們不能誠實地給出固定算力或固定破解時間：它取決於 PIN 是否隨機、長度、攻擊者硬體與實際攻擊路徑。若 PIN 是從 94 個允許的可列印 ASCII 字元均勻隨機選出，離線暴力猜測平均需要 <code>94ⁿ ÷ 2</code> 次。</p><label class="docs-calculator-label" for="zero-pin-length">用於說明的隨機 PIN 長度</label><select id="zero-pin-length" class="docs-calculator"><option value="4">4 個字元</option><option value="8">8 個字元</option><option value="12" selected>12 個字元</option><option value="16">16 個字元</option></select><p class="docs-calculator-result" id="zero-guess-result" aria-live="polite"></p><p class="docs-callout"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i>人為挑選或重複使用的 PIN，實際熵值可能遠低於這個示例。計算器不會要求或接收你的真實 PIN。</p>`,
    ja: `<hr class="docs-rule"><h2 id="secret">AstraSecret：日常的なプライバシー</h2><p>AstraSecret は、自分で保管する 4〜6 桁の PIN でクライアント側から内容を守ります。日常的な私的文章にもう一つの壁を加えたい場合に向きます。短い数字 PIN の推測耐性は限られるため、高価値の秘密に対する最強の選択肢としては扱わないでください。</p><hr class="docs-rule"><h2 id="confidential">AstraConfidential：より強い利用者保管型の保護</h2><p>AstraConfidential は大文字と小文字を区別する、4〜16 文字の印字可能 ASCII PIN を使います。固有でランダムな 12〜16 文字の PIN を強く推奨します。内容はアップロード前にクライアントで暗号化され、アカウントに結び付いた保護とサーバー側保護を組み合わせます。PIN は保存も復旧もされません。</p><hr class="docs-rule"><h2 id="zero">AstraZero：鍵はクライアントだけで生成</h2><p>AstraZero は最もプライバシーを重視する方式です。暗号鍵はクライアントだけで生成され、サーバーには取得可能な同等の環境鍵がありません。サーバーの権限やファイルだけを得ても、攻撃者が持つのは暗号化データであり、直接読める平文ではありません。</p><div class="docs-zero-model"><i class="fa-solid fa-shield-halved" aria-hidden="true"></i><div><strong>サーバーアクセスが露出した場合</strong><span>攻撃者にはさらに PIN、解除中の信頼済み端末の支配、または別の防御境界の突破が必要です。サーバーアクセスだけでは AstraZero ノートを直接読めません。</span></div></div><h3>PIN の推測空間。断定的な解析時間ではありません</h3><p>固定の計算能力や解析時間を正直に示すことはできません。PIN のランダム性、長さ、攻撃者のハードウェア、実際の攻撃経路に依存するためです。94 個の許可された印字可能 ASCII 文字から均等ランダムに選んだ PIN では、オフライン推測の平均回数は <code>94ⁿ ÷ 2</code> です。</p><label class="docs-calculator-label" for="zero-pin-length">説明用のランダム PIN 長</label><select id="zero-pin-length" class="docs-calculator"><option value="4">4 文字</option><option value="8">8 文字</option><option value="12" selected>12 文字</option><option value="16">16 文字</option></select><p class="docs-calculator-result" id="zero-guess-result" aria-live="polite"></p><p class="docs-callout"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i>人が選んだ PIN や再利用した PIN は、この例よりはるかに低いエントロピーになることがあります。計算機は実際の PIN を尋ねたり受け取ったりしません。</p>`,
  };
  const locale = () => {
    const value = document.documentElement.lang || localStorage.getItem("astranote_language") || navigator.language || "en";
    return value.toLowerCase().startsWith("zh") ? "zh-Hant" : value.toLowerCase().startsWith("ja") ? "ja" : "en";
  };
  const route = location.pathname === "/docs" ? "home" : location.pathname.split("/").filter(Boolean).pop();
  const render = () => {
    const root = document.querySelector("#docs-article");
    const item = content[route];
    if (!root || !item) return;
    const lang = locale(); const page = item[lang]; const active = route;
    const nav = sections.map(([slug, icon], i) => `<a href="/docs/${slug}" class="${slug === active ? "active" : ""}"><i class="fa-solid ${icon}" aria-hidden="true"></i>${names[lang][i]}</a>`).join("");
    const label = route === "home" ? (lang === "zh-Hant" ? "文件首頁" : lang === "ja" ? "ドキュメント" : "Documentation") : names[lang][sections.findIndex(([slug]) => slug === route)];
    let body = route === "encryption" ? encryptionGuide[lang] : page.body;
    if (route === "encryption") {
      const normal = lang === "zh-Hant"
        ? "<p class=\"docs-callout\"><i class=\"fa-solid fa-lock\" aria-hidden=\"true\"></i><strong>普通加密（AES-256-GCM）</strong>適合不需要 PIN、但希望加密儲存的情況；舊 AES-128 筆記仍可讀取，但不能再新建。</p>"
        : lang === "ja"
          ? "<p class=\"docs-callout\"><i class=\"fa-solid fa-lock\" aria-hidden=\"true\"></i><strong>通常暗号化（AES-256-GCM）</strong>は PIN を使わずに暗号化保存したい場合の選択肢です。従来の AES-128 ノートは読めますが、新規作成はできません。</p>"
          : "<p class=\"docs-callout\"><i class=\"fa-solid fa-lock\" aria-hidden=\"true\"></i><strong>Normal encryption (AES-256-GCM)</strong> is for encrypted storage without a PIN. Legacy AES-128 notes remain readable, but cannot be newly created.</p>";
      body = body.replace("</section><hr class=\"docs-rule\">", `${normal}</section><hr class=\"docs-rule\">`);
    }
    const protectionNames = lang === "zh-Hant"
      ? { secret: "秘密（AstraSecret）", confidential: "機密（AstraConfidential）", zero: "最高機密（AstraZero）" }
      : lang === "ja"
        ? { secret: "シークレット（AstraSecret）", confidential: "コンフィデンシャル（AstraConfidential）", zero: "最高機密（AstraZero）" }
        : { secret: "Secret (AstraSecret)", confidential: "Confidential (AstraConfidential)", zero: "Top Secret (AstraZero)" };
    body = body
      .replace(/(?<![(（])AstraSecret(?![)）])/gu, protectionNames.secret)
      .replace(/(?<![(（])AstraConfidential(?!\s+SCHybrid|[)）])/gu, protectionNames.confidential)
      .replace(/(?<![(（])AstraZero(?![)）])/gu, protectionNames.zero);
    const current = sections.findIndex(([key]) => key === route);
    const previous = current <= 0 ? ["home", "fa-book-open"] : sections[current - 1];
    const next = current < 0 || current === sections.length - 1 ? null : sections[current + 1];
    const pagePath = (key) => key === "home" ? "/docs" : `/docs/${key}`;
    const previousText = previous[0] === "home" ? (lang === "zh-Hant" ? "文件首頁" : lang === "ja" ? "ドキュメント" : "Documentation") : names[lang][sections.findIndex(([key]) => key === previous[0])];
    const nextText = next ? names[lang][sections.findIndex(([key]) => key === next[0])] : (lang === "zh-Hant" ? "聯絡我們" : lang === "ja" ? "お問い合わせ" : "Contact us");
    const utilityLinks = lang === "zh-Hant"
      ? [["/terms", "fa-scale-balanced", "使用者協議"], ["/privacy", "fa-shield-halved", "隱私政策"], ["https://github.com/NeuralNexusLab-nh/AstraNote", "fa-github", "程式碼庫 · 保留所有權利", true], ["mailto:vdp@nxlabtw.com", "fa-bug", "回報漏洞"]]
      : lang === "ja"
        ? [["/terms", "fa-scale-balanced", "利用規約"], ["/privacy", "fa-shield-halved", "プライバシー"], ["https://github.com/NeuralNexusLab-nh/AstraNote", "fa-github", "リポジトリ · All Rights Reserved", true], ["mailto:vdp@nxlabtw.com", "fa-bug", "脆弱性を報告"]]
        : [["/terms", "fa-scale-balanced", "Terms"], ["/privacy", "fa-shield-halved", "Privacy"], ["https://github.com/NeuralNexusLab-nh/AstraNote", "fa-github", "Repository · All Rights Reserved", true], ["mailto:vdp@nxlabtw.com", "fa-bug", "Report a vulnerability"]];
    root.innerHTML = `<div class="docs-layout"><aside class="docs-sidebar"><a class="docs-sidebar-home ${route === "home" ? "active" : ""}" href="/docs"><i class="fa-solid fa-book-open" aria-hidden="true"></i>${lang === "zh-Hant" ? "文件首頁" : lang === "ja" ? "ドキュメント" : "Documentation"}</a><nav aria-label="Documentation">${nav}</nav><div class="docs-sidebar-links">${utilityLinks.map(([href, icon, text, external]) => `<a href="${href}"${external ? ' target="_blank" rel="noopener noreferrer"' : ""}><i class="fa-${icon === "fa-github" ? "brands" : "solid"} ${icon}" aria-hidden="true"></i>${text}</a>`).join("")}</div></aside><article class="docs-article"><header class="docs-article-head reveal visible"><p class="eyebrow"><i class="fa-solid fa-book-open" aria-hidden="true"></i>${label}</p><h1>${page.title}</h1><p class="muted docs-lead">${page.lead}</p></header><div class="docs-article-body">${body}</div><footer class="docs-next"><a href="${pagePath(previous[0])}"><i class="fa-solid fa-arrow-left" aria-hidden="true"></i><span>${previousText}</span></a>${next ? `<a href="${pagePath(next[0])}"><span>${nextText}</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></a>` : `<a href="mailto:astranote@nxlabtw.com"><span>${nextText}</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></a>`}</footer></article></div>`;
    if (route === "encryption") {
      const names = lang === "zh-Hant"
        ? ["秘密（AstraSecret）", "機密（AstraConfidential）", "最高機密（AstraZero）"]
        : lang === "ja"
          ? ["シークレット（AstraSecret）", "コンフィデンシャル（AstraConfidential）", "最高機密（AstraZero）"]
          : ["Secret (AstraSecret)", "Confidential (AstraConfidential)", "Top Secret (AstraZero)"];
      root.querySelectorAll(".docs-encryption-map article header h2, .docs-protection-compare > div:not(.docs-protection-head) strong")
        .forEach((heading, index) => { heading.textContent = names[index]; });
    }
    const zeroBadge = root.querySelector(".docs-zero-card header b");
    if (zeroBadge) zeroBadge.textContent = lang === "zh-Hant" ? "僅限 Pro 與 Ultra" : lang === "ja" ? "Pro・Ultra 限定" : "Pro & Ultra only";
    const title = `AstraNote - ${page.title}`;
    document.title = title;
    const canonical = route === "home" ? "https://astranote.nxlabtw.com/docs" : `https://astranote.nxlabtw.com/docs/${route}`;
    [
      ["link[rel='canonical']", canonical, "href"],
      ["meta[name='description']", page.lead, "content"],
      ["meta[property='og:title']", title, "content"],
      ["meta[property='og:description']", page.lead, "content"],
      ["meta[name='twitter:title']", title, "content"],
      ["meta[name='twitter:description']", page.lead, "content"],
    ].forEach(([selector, value, attribute]) => document.querySelector(selector)?.setAttribute(attribute, value));
    const calculator = document.querySelector("#zero-pin-length");
    const result = document.querySelector("#zero-guess-result");
    const formatGuesses = () => {
      if (!calculator || !result) return;
      const figures = {
        "4d": ["5 × 10³", "2¹²·³"],
        "6d": ["5 × 10⁵", "2¹⁸·⁹"],
        "12a": ["2.38 × 10²³", "2⁷⁷·⁶"],
        "16a": ["1.86 × 10³¹", "2¹⁰³·⁹"],
      };
      const [decimal, binary] = figures[calculator.value] || figures["12a"];
      result.innerHTML = lang === "zh-Hant" ? `<strong>平均猜測次數</strong><b>${decimal}</b><span>約 ${binary} 種嘗試規模</span>` : lang === "ja" ? `<strong>平均推測回数</strong><b>${decimal}</b><span>約 ${binary} の試行規模</span>` : `<strong>Average guesses</strong><b>${decimal}</b><span>approximately ${binary} possible attempts</span>`;
    };
    calculator?.addEventListener("change", formatGuesses);
    formatGuesses();
  };
  document.addEventListener("DOMContentLoaded", render);
  window.addEventListener("astranote:localechange", render);
})();
